package com.example.lab_10.data

import android.content.ContentValues
import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * MoveLogItem represents a single recorded move entry stored in the SQLite database.
 *
 * @property id Unique primary key ID generated by SQLite database.
 * @property username The username of the currently logged-in player who played the move.
 * @property roundNumber The game round number (e.g., Round 1, Round 2...).
 * @property playerSymbol The marker or player identifier for the move (e.g., "X", "O").
 * @property positionRecord Detailed move position record (e.g., "Placed X at Row 1, Col 2 (Grid 1)").
 * @property timestamp System time when the move occurred (Formatted YYYY-MM-DD HH:mm:ss).
 */
data class MoveLogItem(
    val id: Long,
    val username: String,
    val roundNumber: Int,
    val playerSymbol: String,
    val positionRecord: String,
    val timestamp: String
)

/**
 * GameSummaryItem represents a completed game session summary stored in the SQLite database.
 *
 * @property id Unique primary key ID generated by SQLite database.
 * @property username Logged-in username for the game session.
 * @property totalRounds Total rounds played in that game session.
 * @property p1Score Player 1 total wins.
 * @property p2Score Player 2 / AI total wins.
 * @property drawsScore Total draw games.
 * @property winnerSummary Final game outcome text summary (e.g., "Player 1 won 3 - 1").
 * @property timestamp System time when the new game was started/saved.
 */
data class GameSummaryItem(
    val id: Long,
    val username: String,
    val totalRounds: Int,
    val p1Score: Int,
    val p2Score: Int,
    val drawsScore: Int,
    val winnerSummary: String,
    val timestamp: String
)

/**
 * GameDatabaseHelper handles SQLite database creation, table management, and CRUD operations
 * for storing player move position records, completed game session summaries, round numbers,
 * usernames, and system timestamps.
 *
 * Implements Android's native SQLiteDatabase API using standard SQLiteOpenHelper.
 */
class GameDatabaseHelper(context: Context) : SQLiteOpenHelper(context, DATABASE_NAME, null, DATABASE_VERSION) {

    companion object {
        private const val DATABASE_NAME = "tictactoe_history.db"
        private const val DATABASE_VERSION = 2

        // Table 1: Detailed Move Position Log
        const val TABLE_MOVES = "game_moves"
        const val COLUMN_ID = "id"
        const val COLUMN_USERNAME = "username"
        const val COLUMN_ROUND_NUMBER = "round_number"
        const val COLUMN_PLAYER_SYMBOL = "player_symbol"
        const val COLUMN_POSITION_RECORD = "position_record"
        const val COLUMN_TIMESTAMP = "timestamp"

        // Table 2: Completed Game Session Summaries
        const val TABLE_GAME_SUMMARIES = "game_summaries"
        const val COLUMN_SUMMARY_ID = "id"
        const val COLUMN_SUMMARY_USERNAME = "username"
        const val COLUMN_TOTAL_ROUNDS = "total_rounds"
        const val COLUMN_P1_SCORE = "p1_score"
        const val COLUMN_P2_SCORE = "p2_score"
        const val COLUMN_DRAWS_SCORE = "draws_score"
        const val COLUMN_WINNER_SUMMARY = "winner_summary"
        const val COLUMN_SUMMARY_TIMESTAMP = "timestamp"

        // SQL Query to create game_moves table
        private const val CREATE_TABLE_MOVES = """
            CREATE TABLE $TABLE_MOVES (
                $COLUMN_ID INTEGER PRIMARY KEY AUTOINCREMENT,
                $COLUMN_USERNAME TEXT NOT NULL,
                $COLUMN_ROUND_NUMBER INTEGER NOT NULL,
                $COLUMN_PLAYER_SYMBOL TEXT NOT NULL,
                $COLUMN_POSITION_RECORD TEXT NOT NULL,
                $COLUMN_TIMESTAMP TEXT NOT NULL
            );
        """

        // SQL Query to create game_summaries table
        private const val CREATE_TABLE_SUMMARIES = """
            CREATE TABLE $TABLE_GAME_SUMMARIES (
                $COLUMN_SUMMARY_ID INTEGER PRIMARY KEY AUTOINCREMENT,
                $COLUMN_SUMMARY_USERNAME TEXT NOT NULL,
                $COLUMN_TOTAL_ROUNDS INTEGER NOT NULL,
                $COLUMN_P1_SCORE INTEGER NOT NULL,
                $COLUMN_P2_SCORE INTEGER NOT NULL,
                $COLUMN_DRAWS_SCORE INTEGER NOT NULL,
                $COLUMN_WINNER_SUMMARY TEXT NOT NULL,
                $COLUMN_SUMMARY_TIMESTAMP TEXT NOT NULL
            );
        """
    }

    override fun onCreate(db: SQLiteDatabase) {
        db.execSQL(CREATE_TABLE_MOVES)
        db.execSQL(CREATE_TABLE_SUMMARIES)
    }

    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        db.execSQL("DROP TABLE IF EXISTS $TABLE_MOVES")
        db.execSQL("DROP TABLE IF EXISTS $TABLE_GAME_SUMMARIES")
        onCreate(db)
    }

    /**
     * Inserts a player move input position record into the SQLiteDatabase.
     */
    fun insertMove(
        username: String,
        roundNumber: Int,
        playerSymbol: String,
        positionRecord: String
    ): Long {
        val db = writableDatabase
        val values = ContentValues().apply {
            put(COLUMN_USERNAME, username.ifBlank { "Guest" })
            put(COLUMN_ROUND_NUMBER, roundNumber)
            put(COLUMN_PLAYER_SYMBOL, playerSymbol)
            put(COLUMN_POSITION_RECORD, positionRecord)
            put(COLUMN_TIMESTAMP, getCurrentSystemTime())
        }
        return db.insert(TABLE_MOVES, null, values)
    }

    /**
     * Inserts a completed game session summary into the SQLiteDatabase.
     */
    fun insertGameSummary(
        username: String,
        totalRounds: Int,
        p1Score: Int,
        p2Score: Int,
        drawsScore: Int,
        winnerSummary: String
    ): Long {
        val db = writableDatabase
        val values = ContentValues().apply {
            put(COLUMN_SUMMARY_USERNAME, username.ifBlank { "Guest" })
            put(COLUMN_TOTAL_ROUNDS, totalRounds)
            put(COLUMN_P1_SCORE, p1Score)
            put(COLUMN_P2_SCORE, p2Score)
            put(COLUMN_DRAWS_SCORE, drawsScore)
            put(COLUMN_WINNER_SUMMARY, winnerSummary)
            put(COLUMN_SUMMARY_TIMESTAMP, getCurrentSystemTime())
        }
        return db.insert(TABLE_GAME_SUMMARIES, null, values)
    }

    /**
     * Retrieves all recorded player move entries from the SQLiteDatabase in descending order.
     */
    fun getAllMoveLogs(): List<MoveLogItem> {
        val moveLogs = mutableListOf<MoveLogItem>()
        val db = readableDatabase

        val cursor = db.query(
            TABLE_MOVES,
            null,
            null,
            null,
            null,
            null,
            "$COLUMN_ID DESC"
        )

        cursor.use { c ->
            if (c.moveToFirst()) {
                val idIndex = c.getColumnIndexOrThrow(COLUMN_ID)
                val userIndex = c.getColumnIndexOrThrow(COLUMN_USERNAME)
                val roundIndex = c.getColumnIndexOrThrow(COLUMN_ROUND_NUMBER)
                val symbolIndex = c.getColumnIndexOrThrow(COLUMN_PLAYER_SYMBOL)
                val posIndex = c.getColumnIndexOrThrow(COLUMN_POSITION_RECORD)
                val timeIndex = c.getColumnIndexOrThrow(COLUMN_TIMESTAMP)

                do {
                    moveLogs.add(
                        MoveLogItem(
                            id = c.getLong(idIndex),
                            username = c.getString(userIndex),
                            roundNumber = c.getInt(roundIndex),
                            playerSymbol = c.getString(symbolIndex),
                            positionRecord = c.getString(posIndex),
                            timestamp = c.getString(timeIndex)
                        )
                    )
                } while (c.moveToNext())
            }
        }
        return moveLogs
    }

    /**
     * Retrieves all completed game session summaries from the SQLiteDatabase in descending order.
     */
    fun getAllGameSummaries(): List<GameSummaryItem> {
        val summaries = mutableListOf<GameSummaryItem>()
        val db = readableDatabase

        val cursor = db.query(
            TABLE_GAME_SUMMARIES,
            null,
            null,
            null,
            null,
            null,
            "$COLUMN_SUMMARY_ID DESC"
        )

        cursor.use { c ->
            if (c.moveToFirst()) {
                val idIndex = c.getColumnIndexOrThrow(COLUMN_SUMMARY_ID)
                val userIndex = c.getColumnIndexOrThrow(COLUMN_SUMMARY_USERNAME)
                val roundsIndex = c.getColumnIndexOrThrow(COLUMN_TOTAL_ROUNDS)
                val p1Index = c.getColumnIndexOrThrow(COLUMN_P1_SCORE)
                val p2Index = c.getColumnIndexOrThrow(COLUMN_P2_SCORE)
                val drawsIndex = c.getColumnIndexOrThrow(COLUMN_DRAWS_SCORE)
                val winnerIndex = c.getColumnIndexOrThrow(COLUMN_WINNER_SUMMARY)
                val timeIndex = c.getColumnIndexOrThrow(COLUMN_SUMMARY_TIMESTAMP)

                do {
                    summaries.add(
                        GameSummaryItem(
                            id = c.getLong(idIndex),
                            username = c.getString(userIndex),
                            totalRounds = c.getInt(roundsIndex),
                            p1Score = c.getInt(p1Index),
                            p2Score = c.getInt(p2Index),
                            drawsScore = c.getInt(drawsIndex),
                            winnerSummary = c.getString(winnerIndex),
                            timestamp = c.getString(timeIndex)
                        )
                    )
                } while (c.moveToNext())
            }
        }
        return summaries
    }

    /**
     * Deletes all move history records and game session summaries from SQLite database.
     */
    fun clearAllLogs(): Int {
        val db = writableDatabase
        db.delete(TABLE_GAME_SUMMARIES, null, null)
        return db.delete(TABLE_MOVES, null, null)
    }

    /**
     * Helper utility method to capture current system time (YYYY-MM-DD HH:mm:ss).
     */
    private fun getCurrentSystemTime(): String {
        val dateFormat = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault())
        return dateFormat.format(Date())
    }
}
